import Foundation

/// Two seconds of a tone in each container, made with afconvert and ffmpeg, so classification is tested
/// on real encoder output.
enum EncodedFixtures {
    static let alac = decode("")
    static let alacFastStart = decode("")
    static let aacMoovAtEnd = decode("")
    static let aacFastStart = decode("")
    static let aacADTS = decode("")
    static let mp3 = decode("")

    private static func decode(_ base64: String) -> Data { Data(base64Encoded: base64)! }
}
